-- Importação Organizze — passo 10/10: lançamentos (684 linhas). Correr depois do passo 09.
do $$
declare uid uuid;
begin
  if (select count(*) from auth.users) <> 1 then
    raise exception 'Esperava exatamente 1 utilizador em auth.users.';
  end if;
  select id into uid from auth.users order by created_at limit 1;

  raise notice 'Importação concluída: % contas, % categorias, % lançamentos.', (select count(*) from public.accounts where user_id = uid), (select count(*) from public.categories where user_id = uid), (select count(*) from public.transactions where user_id = uid);
end $$;
